script:
frappe.ui.form.on('AI Settings', {
    refresh: function(frm) {
        let balance = frm.doc.balance_inr || 0;
        let color = balance > 50 ? 'green' : 'red';
        let currency = frm.doc.currency || 'INR';
        let formatted_balance = format_currency(balance, currency);
        frm.dashboard.set_headline('Live Prepaid Wallet Balance: ' + formatted_balance, color);
    }
});
